bool ScriptSession::passiveChance(float chance){if(chance<=0)return false;if(chance>=1)return true;return double(random())/4294967296.<chance;}
bool ScriptSession::criticalChance(const UnitState& unit,const PassiveInfo& passive){
    static const auto table=[](){constexpr int values[]={0,38,147,320,547,819,1126,1461,1815,2184,2562,2953,3333,3781,4203,4607,5000,5799,6666,7706,10000};std::array<jass::Real,21> result{};for(unsigned i=0;i<result.size();++i)result[i]=jass::Real::fromInteger(values[i]).divide(jass::Real::fromInteger(10000));return result;}();
    auto index=unsigned(std::clamp(int(passive.amount*20+.5f),0,20));auto& failures=units_.at(unit.handle)->criticalFailures[passive.ability];if(!failures)failures=1;auto threshold=table[index].multiply(jass::Real::fromInteger(int(std::min(failures,std::uint32_t(INT_MAX)))));auto sample=jass::Real::fromBits(0x3f800000u|(auxiliaryRandom_[3].next()&0x7fffffu)).subtract(jass::Real::fromBits(0x3f800000u));bool success=number(threshold)>=number(sample);if(success)failures=1;else if(failures<INT_MAX)++failures;return success;
}
float ScriptSession::attackDamageBeforeProc(const UnitState& source,const WeaponDefinition& weapon,float damage){bool ranged=weapon.kind!="normal";return std::max(0.f,damage*(1+(ranged?source.aura.rangedDamage:source.aura.meleeDamage)+source.spellBonus(&UnitBuff::damageBonus)-source.spellBonus(&UnitBuff::damageReduction)+source.equipment.damagePercent)+(ranged?source.aura.rangedFlat:source.aura.meleeFlat)+source.spellBonus(&UnitBuff::flatDamage));}
void ScriptSession::prepareAttack(const UnitState& source,const UnitState& target,CombatProjectile& projectile) {
    bool ranged=projectile.definition.kind!="normal";projectile.damage=attackDamageBeforeProc(source,projectile.definition,projectile.damage);projectile.forcedMiss=passiveChance(source.spellBonus(&UnitBuff::missChance));if(source.illusion)return;std::optional<PassiveInfo> critical,bash;float best=projectile.damage;
    for(auto [ability,level]:passiveAbilities(source)){auto& p=passiveInfo(ability,level);if(p.kind==PassiveKind::Pillage){projectile.procs.push_back(p);continue;}if(p.kind==PassiveKind::MissileDefense){projectile.damage*=p.secondary;continue;}if(p.kind==PassiveKind::Feedback){if(passiveTarget(source,target,p))projectile.procs.push_back(p);continue;}if(p.kind==PassiveKind::Demolish){float factor=target.building?p.secondary:target.hero?p.evasion:p.bonus;if(factor>0 && passiveTarget(source,target,p) && passiveChance(p.amount))projectile.damage*=factor;continue;}if(p.kind==PassiveKind::Pulverize){if(!ranged && passiveTarget(source,target,p) && passiveChance(p.amount))projectile.procs.push_back(p);continue;}if((p.kind!=PassiveKind::Critical && p.kind!=PassiveKind::Bash) || (definitions().field(ability,"AbilityData","code")!="ANdb" && !passiveTarget(source,target,p)) || !criticalChance(source,p))continue;if(p.kind==PassiveKind::Critical){float damage=projectile.damage*std::max(1.f,p.secondary)+p.bonus;if(!critical || damage>best){critical=p;best=damage;}}else if(!target.building && (!ranged || !capability(target,"Amim")) && (!bash || p.bonus>bash->bonus || (p.bonus==bash->bonus && p.duration>bash->duration)))bash=p;}
    if(critical){projectile.damage=best;projectile.neverMiss|=critical->neverMiss;projectile.procs.push_back(*critical);}if(bash){projectile.damage=projectile.damage*std::max(1.f,bash->secondary)+bash->bonus;projectile.neverMiss|=bash->neverMiss;projectile.procs.push_back(*bash);projectile.forcedMiss|=passiveChance(bash->evasion);}
}
bool ScriptSession::evadeAttack(const UnitState& target,const CombatProjectile& projectile) {
    if(projectile.neverMiss)return false;if(projectile.forcedMiss)return true;float evasion=0;for(auto [ability,level]:passiveAbilities(target)){auto& p=passiveInfo(ability,level);if(p.kind==PassiveKind::Evasion)evasion=std::max(evasion,p.amount);else if(p.kind==PassiveKind::Critical)evasion=std::max(evasion,p.evasion);}return passiveChance(evasion);
}
void ScriptSession::validateVampirismPotion(std::uint32_t ability,bool hero){
    auto& data=definitions();auto buff=data.field(ability,"AbilityData","BuffID1");auto targets=data.field(ability,"AbilityData","targs1");float bonus=data.number(ability,"AbilityData","DataA1"),steal=data.number(ability,"AbilityData","DataB1"),absolute=data.number(ability,"AbilityData","DataC1"),duration=data.number(ability,"AbilityData",hero?"HeroDur1":"Dur1");if(buff.size()!=4 || targets.empty() || targets=="_" || targets.size()>1024 || !std::isfinite(bonus) || bonus<0 || bonus>1000000 || !std::isfinite(steal) || steal<0 || steal>1000000 || (absolute!=0 && absolute!=1) || !std::isfinite(duration) || duration<=0 || duration>86400)throw std::runtime_error("Invalid vampirism potion source fields");
}
void ScriptSession::applyVampirismPotion(std::uint32_t id,std::uint32_t ability){
    if(!alive(id,NativeKind::Unit))return;auto unit=units_.at(id);auto& data=definitions();SpellInfo spell;spell.ability=ability;spell.level=1;spell.buff=ObjectData::code(data.field(ability,"AbilityData","BuffID1"));spell.duration=data.number(ability,"AbilityData","Dur1");spell.heroDuration=data.number(ability,"AbilityData","HeroDur1");auto death=unit->deathRevision,ownership=unit->ownerRevision;applyBuff(id,id,spell,BuffKind::ItemVampirism);if(!alive(id,NativeKind::Unit) || unit->removing || unit->deathRevision!=death || unit->ownerRevision!=ownership)return;auto found=unit->buffs.find(spell.buff);if(found==unit->buffs.end() || found->second.kind!=BuffKind::ItemVampirism || found->second.originAbility!=ability)return;auto& buff=found->second;buff.flatDamage=data.number(ability,"AbilityData","DataA1");buff.lifeSteal=data.number(ability,"AbilityData","DataB1");buff.lifeStealAbsolute=data.number(ability,"AbilityData","DataC1")!=0;std::stringstream input(data.field(ability,"AbilityData","targs1"));std::string token;while(std::getline(input,token,',')){auto first=token.find_first_not_of(" \t");if(first!=std::string::npos)buff.lifeStealTargets.insert(token.substr(first,token.find_last_not_of(" \t")-first+1));}spellVisual(spell,"CasterArt",id,{unit->x,unit->y});
}
void ScriptSession::attackPassives(const CombatProjectile& p,float damage,const AuraBonuses& defense,std::uint64_t sourceRevision,std::uint64_t targetRevision) {
    if(damage<=0 || !alive(p.source,NativeKind::Unit) || !alive(p.target,NativeKind::Unit))return;auto source=units_.at(p.source),target=units_.at(p.target);if(source->removing || target->removing)return;bool ranged=p.definition.kind!="normal",hostile=enemy(p.owner,target->owner);lavaSpawnHit(p,damage);auto stats=source->aura;auto targetPoint=WorldPoint{target->x,target->y};
    auto attackerDeath=source->deathRevision,defenderDeath=target->deathRevision;for(auto& proc:p.procs)if(proc.kind==PassiveKind::Pulverize && p.visited.size()<=1){pulverizeDamage(p,proc);if(!alive(p.source,NativeKind::Unit) || !alive(p.target,NativeKind::Unit) || source->deathRevision!=attackerDeath || target->deathRevision!=defenderDeath)return;}
    for(auto& proc:p.procs)if(proc.kind==PassiveKind::Bash && p.visited.size()<=1 && number(target->life)>0){SpellInfo spell;spell.ability=proc.ability;spell.buff=proc.buff;spell.duration=proc.duration;spell.heroDuration=proc.heroDuration;applyBuff(p.target,p.source,spell,BuffKind::Stun,!ranged);}
    if(!source->illusion && alive(p.source,NativeKind::Unit) && !source->removing && number(source->life)>0){auto classes=target->classifications(definitions().unitClasses(target->type));bool mechanical=classes.find("mechanical")!=std::string::npos;float auraRecovery=hostile && !target->building && !mechanical?damage*std::max(ranged?0.f:stats.vampiric,source->equipment.vampiric):0,recovery=auraRecovery;for(auto& [id,buff]:source->buffs)if(source->owner==p.owner && source->deathRevision==sourceRevision && (target->deathRevision==targetRevision || (targetRevision!=UINT64_MAX && target->deathRevision==targetRevision+1 && number(target->life)<=0)) && buff.kind==BuffKind::ItemVampirism){auto& allowed=buff.lifeStealTargets;bool category=target->airborne()?allowed.contains("air"):target->building?(allowed.contains("structure") || allowed.contains("ground")):allowed.contains("ground");bool organic=!allowed.contains("organic") || (!target->building && !mechanical);bool ward=classes.find("ward")==std::string::npos || allowed.contains("ward");bool hasRelation=allowed.contains("enemy") || allowed.contains("neutral") || allowed.contains("friend") || allowed.contains("self");bool relation=!hasRelation || (hostile && allowed.contains("enemy")) || (target->owner>=12 && allowed.contains("neutral")) || (!hostile && source->handle!=target->handle && allowed.contains("friend")) || (source->handle==target->handle && allowed.contains("self"));bool hero=!(allowed.contains("hero") || allowed.contains("nonhero")) || (target->hero?allowed.contains("hero"):allowed.contains("nonhero"));if(category && organic && ward && relation && hero)recovery=std::max(recovery,buff.lifeStealAbsolute?buff.lifeSteal:damage*buff.lifeSteal);}if(recovery>0){auto ownerRevision=source->ownerRevision;unitLife(runtime_.handle("unit",p.source),real(number(source->life)+recovery));if(!alive(p.source,NativeKind::Unit) || source->removing || source->deathRevision!=attackerDeath || source->ownerRevision!=ownerRevision || number(source->life)<=0)return;for(auto& [id,aura]:source->auras)if(auraRecovery>0 && aura.definition->kind==PassiveKind::Vampiric && aura.definition->buff){SpellInfo art;art.ability=aura.definition->buff;spellVisual(art,"SpecialArt",p.source,{source->x,source->y});}}}
    if(!ranged && hostile && (defense.thorns!=0 || defense.thornsFlat!=0) && alive(p.source,NativeKind::Unit) && alive(p.target,NativeKind::Unit)){float reflected=std::max(0.f,damage*defense.thorns+defense.thornsFlat);damageUnit(p.target,p.source,reflected,0,21);if(alive(p.source,NativeKind::Unit))for(auto& [id,aura]:target->auras)if(aura.definition->kind==PassiveKind::Thorns && aura.definition->buff){SpellInfo art;art.ability=aura.definition->buff;spellVisual(art,"SpecialArt",p.source,{source->x,source->y});}}
    if(ranged || source->illusion || !alive(p.source,NativeKind::Unit) || source->removing || number(source->life)<=0)return;std::vector<PassiveInfo> cleaves;for(auto [ability,level]:passiveAbilities(*source)){auto& spell=passiveInfo(ability,level);if(spell.kind==PassiveKind::Cleave)cleaves.push_back(spell);}
    for(auto& spell:cleaves){std::vector<std::uint32_t> victims;for(auto& [id,u]:units_)if(id!=p.source && id!=p.target && passiveTarget(*source,*u,spell) && std::hypot(number(u->x)-number(targetPoint.x),number(u->y)-number(targetPoint.y))<=spell.area)victims.push_back(id);for(auto id:victims){if(!alive(p.source,NativeKind::Unit) || source->removing || number(source->life)<=0)return;if(!alive(id,NativeKind::Unit) || !passiveTarget(*source,*units_.at(id),spell))continue;auto u=units_.at(id);damageUnit(p.source,id,p.damage*spell.amount,p.definition.attackType,5);if(alive(id,NativeKind::Unit)){SpellInfo art;art.ability=spell.ability;spellVisual(art,"SpecialArt",id,{u->x,u->y});}}}
}
